1	using System.Globalization;
2	using TutorFlow.Core.Academico;
3	using TutorFlow.Core.Autorizacion;
4	
5	namespace TutorFlow.Core.Asistente;
6	
7	public static class FormateadorDatos
8	{
9	    private const string FormatoNota = "0.0";
10	    private const string FormatoPromedio = "0.00";
11	    private const string SinCalificar = "sin calificar";
12	    internal const string MarcaDelimitadorOriginal = "DATOS_NO_CONFIABLES";
13	    private const string MarcaDelimitadorNeutra = "DATOS NO CONFIABLES";
14	    private const string SinDefinitivaEncabezado = "Sin definitiva (falta calificar un corte)";
15	
16	    private static readonly VozDeLosDatos Segunda = new("Solicita la revisión a tu coordinador", "superaste", "superas", "pierdes");
17	    private static readonly VozDeLosDatos Tercera = new("Solicite la revisión al coordinador del programa", "superó", "supera", "pierde");
18	
19	    public static string Delimitar(string fuente, string contenido) =>
20	        $"<<<{MarcaDelimitadorOriginal} fuente=\"{fuente}\">>>\n"
21	        + contenido.Replace(MarcaDelimitadorOriginal, MarcaDelimitadorNeutra, StringComparison.Ordinal)
22	        + $"\nFIN_{MarcaDelimitadorOriginal}>>>";
23	
24	    public static string DatosBasicos(Estudiante estudiante, DirectorioAcademico directorio)
25	    {
26	        var programa = directorio.Programas.FirstOrDefault(p => p.Id == estudiante.ProgramaId);
27	        var coordinadores = directorio.Coordinadores
28	            .Where(c => c.ProgramasIds.Contains(estudiante.ProgramaId))
29	            .Select(c => c.Nombre)
30	            .ToList();
31	        return $"Estudiante: {estudiante.Nombre} (ID {estudiante.Id}). "
32	            + $"Programa: {estudiante.ProgramaId} ({programa?.Nombre ?? estudiante.ProgramaId}). "
33	            + $"Coordinador del programa: {(coordinadores.Count == 0 ? "sin coordinador asignado" : string.Join(", ", coordinadores))}.";
34	    }
35	
36	    public static string Notas(ResumenEstudiante resumen) => string.Join("\n", LineasDeNotas(resumen));
37	
38	    public static string Asistencia(ResumenEstudiante resumen, bool terceraPersona = false) =>
39	        string.Join("\n", resumen.Asignaturas.Select(resultado => LineaDeAsistencia(resultado, terceraPersona)));
40	
41	    public static string Cortes(IReadOnlyList<NotasAsignatura> notas, string consulta)
42	    {
43	        var coincidencias = BuscarAsignaturas(notas, consulta).Select(LineaDeCortes).ToList();
44	        return coincidencias.Count == 0 ? Textos.AsignaturaNoEncontrada : string.Join(Environment.NewLine, coincidencias);
45	    }
46	
47	    public static IReadOnlyList<NotasAsignatura> BuscarAsignaturas(IReadOnlyList<NotasAsignatura> notas, string consulta)
48	    {
49	        var buscada = NormalizadorTexto.Normalizar(consulta);
50	        return [.. notas.Where(nota => NormalizadorTexto.Normalizar(nota.Nombre).Contains(buscada, StringComparison.Ordinal)
51	            || NormalizadorTexto.Normalizar(nota.Codigo) == buscada)];
52	    }
53	
54	    internal static IEnumerable<string> LineasDeNotas(ResumenEstudiante resumen) =>
55	        LineasDePerdidaPorNota(resumen).Concat(RestoDeLasNotas(resumen));
56	
57	    internal static IEnumerable<string> LineasDePerdidaPorNota(ResumenEstudiante resumen) =>
58	        resumen.Asignaturas.Where(resultado => resultado.Estado == EstadoAsignatura.Perdida).SelectMany(LineasDeEstadoDeLaAsignatura);
59	
60	    internal static IEnumerable<string> RestoDeLasNotas(ResumenEstudiante resumen)
61	    {
62	        var conDefinitiva = resumen.Asignaturas.Where(resultado => resultado.Estado != EstadoAsignatura.SinDefinitiva).ToList();
63	        var lineas = new List<string>();
64	        lineas.AddRange(resumen.Asignaturas.Where(resultado => resultado.Estado != EstadoAsignatura.Perdida).SelectMany(LineasDeEstadoDeLaAsignatura));
65	        lineas.AddRange(conDefinitiva.Count == 0 ? [] : [$"Definitivas: {string.Join(", ", conDefinitiva.Select(DefinitivaEnLinea))}"]);
66	        lineas.AddRange(conDefinitiva.Count == 0 ? [] : [$"Promedio ponderado del periodo: {Promedio(resumen.Promedio)}"]);
67	        lineas.Add($"Nota mínima para aprobar: {Nota(CalculosAcademicos.NotaMinimaAprobacion)}");
68	        lineas.Add($"Créditos matriculados: {resumen.CreditosMatriculados}");
69	        lineas.Add($"Prueba académica: {(resumen.PruebaAcademica ? "sí" : "no")}");
70	        lineas.Add($"Beca por rendimiento: {TextoBeca(resumen.Beca)}");
71	        return lineas;
72	    }
73	
74	    internal static string Promedio(decimal? valor) =>
75	        valor is { } promedio ? promedio.ToString(FormatoPromedio, CultureInfo.InvariantCulture) : "no disponible";
76	
77	    internal static string Nota(decimal? valor) =>
78	        valor is { } nota ? nota.ToString(FormatoNota, CultureInfo.InvariantCulture) : SinCalificar;
79	
80	    internal static string TextoBeca(ElegibilidadBeca beca) => beca switch
81	    {
82	        ElegibilidadBeca.Elegible => "elegible",
83	        ElegibilidadBeca.NoElegible => "no elegible",
84	        _ => "no determinable aún porque hay asignaturas sin definitiva"
85	    };
86	
87	    private static string DefinitivaEnLinea(ResultadoAsignatura resultado) =>
88	        resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia
89	            ? $"{resultado.Asignatura.Nombre} {Nota(0m)} (por inasistencia)"
90	            : $"{resultado.Asignatura.Nombre} {Nota(resultado.Definitiva)}";
91	
92	    private static IEnumerable<string> LineasDeEstadoDeLaAsignatura(ResultadoAsignatura resultado) => resultado.Estado switch
93	    {
94	        EstadoAsignatura.Perdida =>
95	        [
96	            $"Perdida por nota: {resultado.Asignatura.Nombre} (definitiva {Nota(resultado.Definitiva)})",
97	            resultado.Habilitable ? $"Habilitable: {resultado.Asignatura.Nombre}" : $"No habilitable: {resultado.Asignatura.Nombre}"
98	        ],
99	        EstadoAsignatura.PerdidaPorInasistencia =>
100	        [
101	            $"Perdida por inasistencia: {resultado.Asignatura.Nombre} (definitiva {Nota(0m)})",
102	            $"No habilitable: {resultado.Asignatura.Nombre}"
103	        ],
104	        EstadoAsignatura.SinDefinitiva => [LineaSinDefinitiva(resultado), .. LineaDeEquivalente(resultado)],
105	        _ => []
106	    };
107	
108	    private static IEnumerable<string> LineaDeEquivalente(ResultadoAsignatura resultado) =>
109	        resultado.Acumulada is { } acumulada
110	            ? [$"Equivalente de la acumulada de {resultado.Asignatura.Nombre} sobre la nota completa: {Nota(acumulada.EquivalenteSobreEvaluado)}"]
111	            : [];
112	
113	    private static string LineaSinDefinitiva(ResultadoAsignatura resultado) =>
114	        resultado.Acumulada is { } acumulada
115	            ? $"{SinDefinitivaEncabezado}: {resultado.Asignatura.Nombre} (acumulada {Nota(acumulada.Valor)} sobre el {acumulada.PorcentajeEvaluado.ToString("0", CultureInfo.InvariantCulture)}% evaluado)"
116	            : $"{SinDefinitivaEncabezado}: {resultado.Asignatura.Nombre}";
117	
118	    private static string LineaDeCortes(NotasAsignatura nota) =>
119	        $"{nota.Nombre} ({nota.Codigo}): corte 1 {Nota(nota.Cortes.Corte1)} (30%), corte 2 {Nota(nota.Cortes.Corte2)} (30%), corte 3 {Nota(nota.Cortes.Corte3)} (40%).";
120	
121	
122	    internal static string LineaDeAsistencia(ResultadoAsignatura resultado, bool terceraPersona)
123	    {
124	        var voz = terceraPersona ? Tercera : Segunda;
125	        var nombre = resultado.Asignatura.Nombre;
126	        var clases = resultado.Asignatura.Asistencia.ClasesProgramadas;
127	        var maximo = resultado.FaltasPermitidas;
128	        if (resultado.Asignatura.Asistencia.Inasistencias is not { } faltas)
129	        {
130	            return $"{nombre}: sin registro de inasistencias en {clases} clases programadas (máximo sin perder: {maximo}). {voz.Revision} ({Textos.SeccionAsistenciaSinRegistro}).";
131	        }
132	
133	        var restantes = resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia ? 0 : Math.Max(maximo - faltas, 0);
134	        var consecuencia = resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia
135	            ? $"Perdida por inasistencia: {voz.Superaste} {maximo} inasistencias."
136	            : $"Si {voz.Supera} {maximo} inasistencias {voz.Pierde} la asignatura por inasistencia.";
137	        return $"{nombre}: faltas {faltas} de {clases} clases programadas (faltas restantes: {restantes}; máximo sin perder: {maximo}). {consecuencia}";
138	    }
139	
140	    private sealed record VozDeLosDatos(string Revision, string Superaste, string Supera, string Pierde);
141	}
