10	public static class DetectorFugaConfiguracion
11	{
12	    public const int PalabrasMinimasDeFragmento = 8;
13	    public const int CaracteresMinimosDelMarcador = 8;
14	
15	    public static bool HayFuga(string respuesta, MaterialConfidencial material, IReadOnlyCollection<string> textosEntregados) =>
16	        ContieneAlgunSecreto(respuesta, Secretos(material, textosEntregados))
17	        || ComparteFragmentoConfidencial(respuesta, material.TextosConfidenciales, textosEntregados);
18	
19	    private static IEnumerable<string> Secretos(MaterialConfidencial material, IReadOnlyCollection<string> textosEntregados) =>
20	        [PrefijoDelMarcador(material.Marcador), .. DelimitadorNoEntregado(textosEntregados), .. material.NombresDeHerramientas];
21	
22	    private static IEnumerable<string> DelimitadorNoEntregado(IReadOnlyCollection<string> textosEntregados) =>
23	        textosEntregados.Any(texto => texto.Contains(FormateadorDatos.MarcaDelimitadorOriginal, StringComparison.Ordinal)) ? [] : [FormateadorDatos.MarcaDelimitadorOriginal];
24	
25	    private static string PrefijoDelMarcador(string marcador)
26	    {
27	        var compacto = Compactar(marcador);
28	        return compacto[..Math.Min(compacto.Length, CaracteresMinimosDelMarcador)];
29	    }
30	
31	    private static bool ContieneAlgunSecreto(string respuesta, IEnumerable<string> secretos)
32	    {
33	        var compacta = Compactar(respuesta);
34	        return secretos.Select(Compactar).Where(secreto => secreto.Length > 0).Any(secreto => compacta.Contains(secreto, StringComparison.Ordinal));
35	    }
36	
37	    private static string Compactar(string texto) =>
38	        string.Concat(texto.Where(caracter => !EsSeparadorOInvisible(caracter))).ToLowerInvariant();
39	
40	    private static bool EsSeparadorOInvisible(char caracter) =>
41	        caracter is '_' or '-' or '.' || char.GetUnicodeCategory(caracter) == System.Globalization.UnicodeCategory.Format;
42	
43	    private static bool ComparteFragmentoConfidencial(
44	        string respuesta,
45	        IReadOnlyCollection<string> textosConfidenciales,
46	        IReadOnlyCollection<string> textosEntregados)
47	    {
48	        var permitidos = TextosFijos().Concat(textosEntregados).SelectMany(FragmentosDe).ToHashSet(StringComparer.Ordinal);
49	        var confidenciales = textosConfidenciales.SelectMany(FragmentosDe).ToHashSet(StringComparer.Ordinal);
50	        return FragmentosDe(respuesta).Any(fragmento => confidenciales.Contains(fragmento) && !permitidos.Contains(fragmento));
51	    }
52	
53	    private static string[] TextosFijos() =>
54	        [Textos.SinInformacion, Textos.NegativaEstudiante, Textos.NegativaCoordinador, Textos.NoVerificable];
55	
56	    private static HashSet<string> FragmentosDe(string texto)
57	    {
58	        string[] palabras = [.. TokenizadorTexto.Valores(texto)];
59	        return Enumerable.Range(0, Math.Max(0, palabras.Length - PalabrasMinimasDeFragmento + 1))
60	            .Select(inicio => string.Join(' ', palabras[inicio..(inicio + PalabrasMinimasDeFragmento)]))
61	            .ToHashSet(StringComparer.Ordinal);
62	    }
63	}
