7	internal static class EnterosDeAsistencia
8	{
9	    private const int PalabrasHastaLaPalabraClave = 3;
10	
11	    private static readonly HashSet<string> PalabrasClave = new(StringComparer.Ordinal)
12	    {
13	        "falta", "faltas", "inasistencia", "inasistencias", "clase", "clases"
14	    };
15	
16	    private static readonly HashSet<string> PalabrasQueExcluyen = new(StringComparer.Ordinal)
17	    {
18	        "corte", "cortes", "semana", "semanas", "nivel", "seccion", "secciones", "articulo", "articulos", "art"
19	    };
20	
21	    private static readonly HashSet<string> Conectores = new(StringComparer.Ordinal) { "y", "e", "a" };
22	
23	    public static HashSet<string> De(ResumenEstudiante resumen) =>
24	        resumen.Asignaturas
25	            .SelectMany(resultado => new int?[]
26	            {
27	                resultado.Asignatura.Asistencia.Inasistencias,
28	                resultado.Asignatura.Asistencia.ClasesProgramadas,
29	                resultado.FaltasPermitidas,
30	                resultado.FaltasRestantes
31	            })
32	            .OfType<int>()
33	            .Select(entero => entero.ToString(CultureInfo.InvariantCulture))
34	            .ToHashSet(StringComparer.Ordinal);
35	
36	    public static IEnumerable<string> Candidatos(string texto, IReadOnlyList<TokenTexto> tokens) =>
37	        Enumerable.Range(0, tokens.Count)
38	            .Where(indice => EsEntero(tokens[indice]) && !EsPorcentaje(texto, tokens[indice]) && !EsParteDeUnNombre(texto, tokens[indice]))
39	            .Where(indice => !ExcluidoPorLaPalabraPrevia(tokens, indice) && TienePalabraClaveCerca(tokens, indice))
40	            .Select(indice => tokens[indice].Valor);
41	
42	    private static bool EsEntero(TokenTexto token) => token.Valor.All(char.IsAsciiDigit);
43	
44	    private static bool EsParteDeUnNombre(string texto, TokenTexto token) =>
45	        CaracterEn(texto, token.Inicio - 1) == '_' || CaracterEn(texto, token.Fin) == '_' || EsExtensionDeArchivo(texto, token);
46	
47	    private static bool EsExtensionDeArchivo(string texto, TokenTexto token) =>
48	        CaracterEn(texto, token.Fin) == '.' && char.IsLetter(CaracterEn(texto, token.Fin + 1));
49	
50	    private static char CaracterEn(string texto, int posicion) =>
51	        posicion >= 0 && posicion < texto.Length ? texto[posicion] : ' ';
52	
53	    private static bool EsPorcentaje(string texto, TokenTexto token) =>
54	        texto[token.Fin..].TrimStart().StartsWith('%');
55	
56	    private static bool ExcluidoPorLaPalabraPrevia(IReadOnlyList<TokenTexto> tokens, int indice)
57	    {
58	        var anterior = indice - 1;
59	        while (anterior >= 0 && (EsEntero(tokens[anterior]) || Conectores.Contains(tokens[anterior].Valor)))
60	        {
61	            anterior--;
62	        }
63	
64	        return anterior >= 0 && PalabrasQueExcluyen.Contains(tokens[anterior].Valor);
65	    }
66	
67	    private static bool TienePalabraClaveCerca(IReadOnlyList<TokenTexto> tokens, int indice) =>
68	        Enumerable.Range(Math.Max(0, indice - PalabrasHastaLaPalabraClave), (2 * PalabrasHastaLaPalabraClave) + 1)
69	            .Where(posicion => posicion < tokens.Count)
70	            .Any(posicion => PalabrasClave.Contains(tokens[posicion].Valor));
