        Enumerable.Range(Math.Max(0, indice - PalabrasHastaLaPalabraClave), (2 * PalabrasHastaLaPalabraClave) + 1)
            .Where(posicion => posicion < tokens.Count)
            .Any(posicion => PalabrasClave.Contains(tokens[posicion].Valor));
}

